var openReason = (row, sources, rulings) => {
  if (row.Struck) {
    return null;
  }
  if (row.Gone) {
    return "gone from the row script; only a strike closes it";
  }
  for (const field of fieldsOf(row)) {
    const stale = sources.staleCite(row[field]);
    if (stale !== null) {
      return `stale: ${field} cites ${stale.File}, and the quote is gone`;
    }
  }
  if (hasConfirmedChain(row)) {
    return null;
  }
  for (const field of expectedFieldsOf(row)) {
    const held = row[field];
    if (isQuestion(held) && !rulings.has(pairKey(row.Id, field))) {
      return `question for the user: ${field}`;
    }
    if (!isValue(held)) {
      return `unfilled: ${FILL}.${field}`;
    }
  }
  if (!isValue(row[TEST])) {
    return "no confirmed test";
  }
  const ran = row.Ran;
  if (ran === void 0 || ran === "not-run") {
    return "no run result";
  }
  if (ran !== expectedColour(row)) {
    return `ran ${ran}, the table expects ${expectedColour(row)}`;
  }
  return null;
};
var cmdOpen = (caseArg) => {
  const theCase = loadCase(caseArg);
  const table = readTable(theCase);
  if (table.length === 0) {
    console.log("the table has no rows; the row script printed none.");
    return 1;
  }
  const sources = new Sources(theCase.root);
  const rulings = readRulings(theCase);
  const openRows = [];
  for (const row of table) {
    const reason = openReason(row, sources, rulings);
    if (reason !== null) {
      openRows.push([row, reason]);
    }
  }
  if (openRows.length > 0) {
    console.log(`${openRows.length} of the case's ${table.length} rows are open:`);
    for (const [row, reason] of openRows) {
      console.log(`  ${row.Id}: ${reason}`);
    }
  } else {
    console.log("0 rows open; every row closed.");
  }
  const asks = [];
  for (const row of table) {
    if (row.Struck) {
      continue;
    }
    for (const field of fieldsOf(row)) {
      const held = row[field];
      if (isQuestion(held) && !rulings.has(pairKey(row.Id, field))) {
        asks.push(`  ${row.Id}: ${held.Question} (recommended: ${held.Recommend})`);
      }
    }
  }
  if (asks.length > 0) {
    console.log("rows for the user:");
    for (const line of asks) {
      console.log(line);
    }
  }
  const fromToday = [];
  for (const row of table) {
    if (row.Struck || row.Gone) {
      continue;
    }
    for (const field of expectedFieldsOf(row)) {
      const held = row[field];
      if (isValue(held) && held.Source === "today") {
        fromToday.push(`  ${row.Id}: ${field}`);
      }
    }
  }
  if (fromToday.length > 0) {
    console.log("expected from today's code:");
    for (const line of fromToday) {
      console.log(line);
    }
  }
  return openRows.length > 0 ? 1 : 0;
};
var main = (argv) => {
  let exit = 0;
  const program2 = new Command("ledger.ts").description("Checks, merges, and lists the records of a test-oracle case: a folder named __oracle__.").exitOverride();
  program2.command("freeze <case>").description("record the user's word that the row script is right, and pin the script's sha256, in frozen.json").requiredOption("--words <words>", "the user's words").action((caseArg, options) => {
    exit = cmdFreeze(caseArg, options.words);
  });
  program2.command("rows <case>").description("run the row script (the command in oracle.conf.json, given the case folder's path) and merge its rows into table/rows.jsonl").option("--draft", "print the rows and write nothing").action((caseArg, options) => {
    exit = cmdRows(caseArg, options.draft === true);
  });
  program2.command("check <case> <pass> <slice>").description("the parity gate; <pass> is fill or test").action((caseArg, passName, sliceName) => {
    exit = cmdCheck(caseArg, passName, sliceName);
  });
  program2.command("merge <case> <pass> <slice>").description("merge the fields a verdict confirmed; <pass> is fill or test").action((caseArg, passName, sliceName) => {
    exit = cmdMerge(caseArg, passName, sliceName);
  });
  program2.command("results <case> <junit...>").description("write Ran from JUnit XML files and judge the rows").option("--slice <slice>", "judge only this slice").action((caseArg, files, options) => {
    exit = cmdResults(caseArg, files, options.slice);
  });
  program2.command("rule <case> <id> <field>").description("record the user's ruling").requiredOption("--words <words>", "the user's words").action((caseArg, rowId, field, options) => {
    exit = cmdRule(caseArg, rowId, field, options.words);
  });
  program2.command("strike <case> <id>").description("record the user's strike").requiredOption("--why <why>", "the user's words").action((caseArg, rowId, options) => {
    exit = cmdStrike(caseArg, rowId, options.why);
  });
  program2.command("open <case>").description("say where the case stands").action((caseArg) => {
    exit = cmdOpen(caseArg);
  });
  try {
    program2.parse(argv, { from: "user" });
  } catch (error62) {
    if (error62 instanceof CommanderError) {
      return error62.exitCode === 0 ? 0 : 2;
    }
    if (error62 instanceof RecordError) {
      console.error(error62.problems.join("\n"));
      return 2;
    }
    throw error62;
  }
  return exit;
};
process.exitCode = main(process.argv.slice(2));
